public static async Task<byte[]> RasterPreviewAsync(
    Stream csvDerivedPng,
    CancellationToken cancellationToken)
{
    await using var input = csvDerivedPng;
    using var bitmap = SKBitmap.Decode(input);
    if (bitmap is null)
    {
        return [];
    }

    using var image = SKImage.FromBitmap(bitmap);
    cancellationToken.ThrowIfCancellationRequested();
    return image.Encode(SKEncodedImageFormat.Webp, 80).ToArray();
}
